import React, { Component } from 'react';
import {
  Platform,
  StyleSheet,
  Text,
  View,
  Image,
  FlatList,
  ActivityIndicator,
  Alert,
  Dimensions,
  Button,
  BackHandler,
  TouchableNativeFeedback
} from 'react-native';
import { Icon } from 'react-native-elements'
import firebase from 'react-native-firebase';
import {GiftedChat, Bubble, SystemMessage, Message} from 'react-native-gifted-chat';
import Pdf from 'react-native-pdf';
import Modal from 'react-native-modal';
import ImagePicker from 'react-native-image-crop-picker';
import DocumentPicker from 'react-native-document-picker';
import axios from 'axios';

const SCREEN_WIDTH = Dimensions.get('window').width;
const SCREEN_HEIGHT = Dimensions.get('window').height

export default class Example extends Component {
  static navigationOptions= ({ navigation }) => ({
        header: null
      });
  constructor(props) {
    super(props);
    this.state = {
      messages: [],
      loadEarlier: true,
      typingText: null,
      isLoadingEarlier: false,
      uploaded: '',
      showFab: false,
      tempMsgs: [],
      counter: 0,
      point: 0,
      username: '',
      name: '',
      allMessages: [],
      marker: 15,
      viewPdf: false,
      pdfLink: '',
      pdfName: '',
    };

    this._isMounted = false;
    this.handleBackButton = this.handleBackButton.bind(this);
    this.onSend = this.onSend.bind(this);
    this.renderBubble = this.renderBubble.bind(this);
    this.renderSystemMessage = this.renderSystemMessage.bind(this);
    this.renderFooter = this.renderFooter.bind(this);
    this.onLoadEarlier = this.onLoadEarlier.bind(this);
    this.imageMessageCreater = this.imageMessageCreater.bind(this);
    this.chatActions = this.chatActions.bind(this);
    this.uuidv4 = this.uuidv4.bind(this);
    this.imageUploadLink = this.imageUploadLink.bind(this);
    this.renderDoc = this.renderDoc.bind(this);
    this.openCamera = this.openCamera.bind(this);
    this.openPicker = this.openPicker.bind(this);
    this.filePicker = this.filePicker.bind(this);
    this.createTempMsg = this.createTempMsg.bind(this);
    this.renderTempMsgs = this.renderTempMsgs.bind(this);

    this._isAlright = null;
  }

  componentWillMount() {
    this._isMounted = true;
    
  }


  componentDidMount(){
    console.log("dsmdslk: "+JSON.stringify(this.props.navigation.state.params));
    axios.get(`https://classcast-198812.appspot.com/users/getNameFromUsername`)
      .then(res=> {
        console.log("xsnjasjk :"+JSON.stringify(res.data));
        this.setState({ name: res.data });
      })
      .catch(err=> {
        console.log("xsnjasjkerror :"+err)
      });

    BackHandler.addEventListener('hardwareBackPress', this.handleBackButton);
    this.setState({username: firebase.auth().currentUser['phoneNumber'].slice(3,13)});
    const db = firebase.firestore()
    db.collection('chats')
      .doc(this.props.navigation.state.params.chat_id)
        .onSnapshot((doc)=> {
          if (doc.exists) {
            this.setState({allMessages: doc.data().messages.reverse()})
            console.log("byfiuffiu: "+JSON.stringify(this.state.allMessages));
            this.setState({messages: doc.data().messages.slice(0, this.state.marker)})
            console.log("byfiuffiu1: "+ JSON.stringify(this.state.messages));
          }
        }),
        (error) => {
        console.error(error);
        };
  }

  componentWillUnmount() {
    this._isMounted = false;
    BackHandler.removeEventListener('hardwareBackPress', this.handleBackButton);
  }

  handleBackButton() {
    this.props.navigation.goBack(null);
    return true;
  }

  onLoadEarlier() {
    this.setState((previousState) => {
      return {
        isLoadingEarlier: true,
      };
    });

  setTimeout(() => {
    if (this._isMounted === true) {
      this.setState((previousState) => {
        return {
          messages: this.state.allMessages.slice(0, this.state.marker + 15),
          isLoadingEarlier: false,
          marker: this.state.marker +15
        };
      });
    }
    if (this.state.allMessages.length <= (this.state.marker - 15)){
      this.setState({loadEarlier: false})
    }
  }, 1000); 
  }

  uuidv4() {
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
      var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
      return v.toString(16);
    }); }
  
  createTempMsg(link, name, type){
    if (type == 'image' ){
      let message={
        _id: this.uuidv4(),
        createdAt: Math.floor(Date.now()),
        uploaded: 0,
        user: {
          _id: this.state.username,
          name: this.state.name
        },
        image: link
      }
      this.setState(prevState => ({
        tempMsgs: [...prevState.tempMsgs, message]
      }))
    }

    else {
      let message={
        _id: this.uuidv4(),
        createdAt: Math.floor(Date.now()),
        uploaded: 0,
        user: {
          _id: this.state.username,
          name: this.state.name
        },
        doc: link,
        docName: name
      }
      this.setState(prevState => ({
        tempMsgs: [...prevState.tempMsgs, message]
      }))
    }
  }

  imageMessageCreater(link, type, name){
    if (type == 'image' ){
      let message={
        _id: this.uuidv4(),
        createdAt: Math.floor(Date.now()),
        user: {
          _id: this.state.username,
          name: this.state.name
        },
        image: link
      }
      const db = firebase.firestore().collection('chats').doc(this.props.navigation.state.params.chat_id);
      db.update({
        messages: firebase.firestore.FieldValue.arrayUnion(message)
      })
      return message;
    }

    else {
      let message={
        _id: this.uuidv4(),
        createdAt: Math.floor(Date.now()),
        user: {
          _id: this.state.username,
          name: this.state.name
        },
        doc: link,
        docName: name
      }
      const db = firebase.firestore().collection('chats').doc(this.props.navigation.state.params.chat_id);
      db.update({
        messages: firebase.firestore.FieldValue.arrayUnion(message)
      })
      return message;
    }
  }

  onSend(messages) {
    messages[0].createdAt = Math.floor(Date.now());
    console.log("Message :"+ JSON.stringify(messages[0]));
    console.log("Message :"+ JSON.stringify(this.props.navigation.state.params));
    const db = firebase.firestore().collection('chats').doc(this.props.navigation.state.params.chat_id);
    db.update({
      messages: firebase.firestore.FieldValue.arrayUnion(messages[0])
    })
    console.log("sajgavssac: "+JSON.stringify(this.props.navigation.state.params));
    axios.post(`https://classcast-198812.appspot.com/teachersapp/update_chat_list_student`, { "chat_id": this.props.navigation.state.params.chat_id })
    .then(res=>{
      console.log("update_chat_list: "+JSON.stringify(res.data)+'||'+this.props.navigation.state.params.chat_id)
    })
    .catch(err=> {
      console.log("update_chat_list"+err);
    })
  }

  imageUploadLink(type, name) {
    if (this.state.uploaded != ''){
      firebase.storage().ref(this.state.uploaded).getDownloadURL()
      .then((url) =>
        { this.imageMessageCreater(url,type, name)
          this.setState({ uploaded: ''}) }) }
  }

  uploadFile(uri, name, type, counter){
    let path= 'something/' + name;
    let uploaded = false;
    console.log('dsdasiasjkdakjsjaskd :'+name);
    firebase.storage()
        .ref(path)
        .putFile(uri).on(
            firebase.storage.TaskEvent.STATE_CHANGED,
            (snapshot) => {
            let state = {};
            console.log("progress1:" + JSON.stringify(snapshot));
            this.setState({
              progress: (snapshot.bytesTransferred / snapshot.totalBytes) * 100 // Calculate progress percentage
            });
            console.log("progress:" + this.state.progress);


            if (snapshot.state === firebase.storage.TaskState.SUCCESS) {
              if(!uploaded){
                uploaded=true
                var randomID= 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
                  var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
                  return v.toString(16);
                });
                if (type == 'image' ){
                  let message={
                    _id: randomID,
                    createdAt: Math.floor(Date.now()),
                    user: {
                      _id: this.state.username,
                      name: this.state.name
                    },
                    image: snapshot.downloadURL
                  }
                  const db = firebase.firestore().collection('chats').doc(this.props.navigation.state.params.chat_id);
                  db.update({
                    messages: firebase.firestore.FieldValue.arrayUnion(message)
                  })
                }
            
                else {
                  let message={
                    _id: randomID,
                    createdAt: Math.floor(Date.now()),
                    user: {
                      _id: this.state.username,
                      name: this.state.name
                    },
                    doc: snapshot.downloadURL,
                    docName: name
                  }
                  const db = firebase.firestore().collection('chats').doc(this.props.navigation.state.params.chat_id);
                  db.update({
                    messages: firebase.firestore.FieldValue.arrayUnion(message)
                  })
                }
                }
              state = {
                ...state,
                uploading: false,
                progress: 0,
                uploaded: path
              };
              let msgs = this.state.tempMsgs;
              msgs[counter].uploaded = 1;
              this.setState({tempMsgs: msgs});
            }
            this.setState(state);
          },
            (error) => {
            console.error(error);
            },
      
    );

  }

  openCamera(){
    ImagePicker.openCamera({
      width: 300,
      height: 400,
    }).then(image => {
      console.log("auaaaa: "+image.path);
      this.createTempMsg(image.path, image.modificationDate, "image")
      this.uploadFile(image.path, image.modificationDate, "image", this.state.counter) 
      this.setState({counter: this.state.counter +1}) 
    })
  }

  openPicker(){
    ImagePicker.openPicker({
      width: 300,
      height: 400,
      cropping: true}).then(image => {
      console.log("auaaaa: "+image.path);
      this.createTempMsg(image.path, image.modificationDate, "image")
      this.uploadFile(image.path, image.modificationDate, "image", this.state.counter) 
      this.setState({counter: this.state.counter +1}) 
    })
  }

  async filePicker(){

    const res = await DocumentPicker.pick({
      type: [DocumentPicker.types.pdf],
    });
    this.createTempMsg(res.uri, res.name, "doc")
    this.uploadFile(res.uri, res.name, "doc", this.state.counter)
    this.setState({counter: this.state.counter +1}) 
  } catch (err) {
    if (DocumentPicker.isCancel(err)) {
      // User cancelled the picker, exit any dialogs or menus and move on
    } else {
      throw err;
    }

  }

  chatActions(){
    return(
      <View style={{backgroundColor: 'white', borderWidth: 1, borderColor:'grey',  height: 0.065*SCREEN_HEIGHT, borderRadius: 0.04*SCREEN_HEIGHT, padding: 0.03 * SCREEN_WIDTH, flexDirection: 'row', justifyContent: 'center', alignitems: 'center', alignSelf: 'center'}} >
          <Icon type="font-awesome" name="plus" color={'grey'} onPress={()=>
                  {this.setState({showFab: !this.state.showFab}) }}/>
          { (this.state.showFab) &&
          <View style={{flexDirection:'row', padding: 0.01 * SCREEN_WIDTH, justifyContent: 'center', alignSelf: 'center'}}>
            <View style={{ marginRight: 0.07 * SCREEN_WIDTH, marginLeft: 0.07 * SCREEN_WIDTH }}>
              <Icon type="font-awesome" name="camera" color={'#5157AE'} onPress={()=>{this.openCamera()}}/>
            </View>
            <View style={{ marginRight: 0.07 * SCREEN_WIDTH }}>
              <Icon type="font-awesome" name="image" color={'#F17904'} onPress={()=>{this.openPicker()}}/>
            </View>
            <View style={{ marginRight: 0.02 * SCREEN_WIDTH }}>
              <Icon type="font-awesome" name="file"  color={'#5CB3A1'} onPress={()=>{this.filePicker()}}/>
            </View>
          </View>
          }
      </View>
      
      
    );
      
}

  answerDemo(messages) {
    if (messages.length > 0) {
      if ((messages[0].image || messages[0].location) || !this._isAlright) {
        this.setState((previousState) => {
          return {
            typingText: 'React Native is typing'
          };
        });
      }
    }

  setTimeout(() => {
    if (this._isMounted === true) {
      if (messages.length > 0) {
        if (messages[0].image) {
          this.onReceive('Nice picture!');
        } else if (messages[0].location) {
          this.onReceive('My favorite place');
        } else {
          if (!this._isAlright) {
            this._isAlright = true;
            this.onReceive('Alright');
          }
        }
      }
    }
    this.setState((previousState) => {
      return {
        typingText: null,
      };
    });
    }, 1000);
  }

  renderDoc(props){
    if (props.currentMessage.doc ) {
      console.log("wdkadoajsdo: "+JSON.stringify(props));
    return(
      <TouchableNativeFeedback onPress={()=> {
        console.log("mspmpdsmd: "+props.currentMessage.doc);
        this.setState({viewPdf: true});
        this.setState({pdfLink: props.currentMessage.doc});
        this.setState({pdfName: props.currentMessage.docName});
        //this.renderPdf(props.currentMessage.doc);
      }}>
        <View style={{flexDirection: 'row', backgroundColor: '#c3f796', padding: 5, margin: 5,  borderRadius:4, flexWrap: 'wrap', width: 0.7 * SCREEN_WIDTH, justifyContent: 'center'}}>
          <Icon type="font-awesome" name="file" style={{color:'grey', fontSize: 18, flex: 1, alignSelf: 'center', marginRight: 0.005 * SCREEN_WIDTH}}/>
          <Text style={{color:'black', fontSize: 15, alignSelf:'center', flexWrap: 'wrap', flex: 9, marginLeft: 0.01 * SCREEN_WIDTH}}>{props.currentMessage.docName}</Text>
        </View>
      </TouchableNativeFeedback>
    )
    }
  }

  renderBubble(props) {
    return (
        <Bubble
          {...props}
          wrapperStyle={{
            elevation:5,
            left: {
              borderRadius: 4,
              backgroundColor: 'white',
            },
            right: {
              borderRadius: 4,
              backgroundColor: '#0099ff'
            }
          }}
          textStyle={{
            fontSize: 14,
            color:'black'
          }}
          />
    );
  }

  renderSystemMessage(props) {
    return (
      <SystemMessage
        {...props}
        containerStyle={{
          marginBottom: 15,
        }}
        textStyle={{
          fontSize: 14,
          color:'black'
        }}
      />
    );
  }

  renderCustomView(props) {
    return (
      <Icon type="font-awesome" name="paperclip"/>
    );
  }

  renderLoading(){
    return(
    <View>
      <ActivityIndicator size="large" color="red" />
    </View>
    )
  }

  renderTempMsgs(item, index){
    
    const point = item.index;
    if(!this.state.tempMsgs[point].uploaded) {
      return(
          <Message
          renderBubble = {this.renderBubble}
          renderAvatar = {this.renderLoading}
          showUserAvatar ={false} position={'right'} currentMessage= {item.item}/>      
      )
    }
    else{
      return(
        <View></View>
      )
    }

  }


  renderFooter() {
    if (this.state.tempMsgs) {
    return (
    <FlatList
        data={this.state.tempMsgs}
        renderItem={this.renderTempMsgs.bind(this)}
        keyExtractor = {(item, index) => index.toString()}
        extraData={this.state}
      />  
    );  
    }
    else return null;
  }


  render() {
    return (

      <View style={{ flex: 1, backgroundColor:'#E5DDD5'}}>
      <Modal backdropOpacity={0.6}
            backdropColor="black"
            transparent={true}
            isVisible={this.state.viewPdf}
            onRequestClose={() => {
              this.setState({viewPdf: false});
              this.setState({pdfLink: ''});
              this.setState({pdfName: ''});
          }}>
          <View style={styles.tncModal}>
          
          <TouchableNativeFeedback
            onPress={()=> {
              this.setState({viewPdf: false});
            }}>
            <View style={{ alignSelf: 'flex-end'}}>
              <Icon type="font-awesome" name="times" active={false} style={{fontSize: 0.05 * SCREEN_WIDTH, color: 'black', alignSelf: 'flex-end'}} /> 
            </View>
          </TouchableNativeFeedback>
          <Text style={styles.tncHeadingBig}>{this.state.pdfName}</Text>
          <Pdf
              source={{uri: this.state.pdfLink}}
              onLoadComplete={(numberOfPages,filePath)=>{
                  console.log(`number of pages: ${numberOfPages}`);
              }}
              onPageChanged={(page,numberOfPages)=>{
                  console.log(`current page: ${page}`);
              }}
              onError={(error)=>{
                  console.log(error);
              }}
              style={styles.pdf}/>
          </View>
        </Modal>
        <Image source={{uri:'data:image/png;base64,'}}
          style={{height: 0.9 * SCREEN_HEIGHT, width: '95%', position: 'absolute', opacity: 0.9, resizeMode: 'cover', alignSelf: 'center'}} />
          <View style={{flexDirection: 'row',paddingBottom: 0.01 * SCREEN_HEIGHT, paddingTop: 0.05 * SCREEN_HEIGHT, alignSelf: 'center'}}>
            <TouchableNativeFeedback style={{flex: 1, paddingLeft: 0.01 * SCREEN_WIDTH}}>
              <Icon type='font-awesome' name='arrow-left' style={{alignSelf: 'flex-start'}} color={'black'} onPress={()=>{this.props.navigation.goBack()}}  />
            </TouchableNativeFeedback>
            <View style={{flex: 8}}>
              <Text style={{fontFamily: 'Montserrat-SemiBold', fontSize: 0.06 * SCREEN_WIDTH, color:'black', textAlign: 'center'}}>{this.props.navigation.state.params.name}</Text>
            </View>
            <View style={{flex: 1}}>
            </View>
          </View>

        <GiftedChat
          messages={this.state.messages}
          onSend={this.onSend}
          loadEarlier={this.state.loadEarlier}
          onLoadEarlier={this.onLoadEarlier}
          isLoadingEarlier={this.state.isLoadingEarlier}

          user={{
            _id: this.state.username,
            name: this.state.name
          }}
          renderActions={this.chatActions.bind(this)}
          renderBubble={this.renderBubble}
          renderSystemMessage={this.renderSystemMessage}
          renderFooter = {this.renderFooter}
          extraData  = {this.state}
          renderCustomView ={this.renderDoc}
        />
      </View>

      
    );
  }
}

